-- PT102-S4-Q21. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT102-S4-Q21$batch05$ AND q.stimulus=$batch05$Sarah: Some schools seek to foster a habit of volunteering in their students by requiring them to perform community service. But since a person who has been forced to do something has not really volunteered and since the habit of volunteering cannot be said to have been fostered in a person who has not yet volunteered for anything, there is no way this policy can succeed by itself.

Paul: I disagree. Some students forced to perform community service have enjoyed it so much that they subsequently actually volunteer to do something similar. In such cases, the policy can clearly be said to have fostered a habit of volunteering.$batch05$ AND q.prompt=$batch05$Paul responds to Sarah's argument using which one of the following argumentative techniques?$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT102-S4-Q21'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT102-S4-Q21$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S4-Q21'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT102-S4-Q21$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Paul) The policy can foster a habit of volunteering.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Some students forced into community service enjoyed it so much that they later volunteered for something similar.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Sarah's argument quietly assumes that forced service can never lead to real volunteering later. Paul agrees that forced service is not volunteering. What he points out is that it can lead to volunteering *afterward*. Those real cases undercut the assumption Sarah needed.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Introducing a consideration that undercuts one of Sarah's assumptions.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT102-S4-Q21$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Paul does not say Sarah's argument is circular.$batch05$), ($batch05$B$batch05$, $batch05$Paul accepts Sarah's definition. Forced service is not volunteering. He finds volunteering in what happens later.$batch05$), ($batch05$C$batch05$, $batch05$The assumption is that forced service never leads to a later habit of volunteering. The consideration is the students who enjoyed it and then volunteered. Paul uses the second to call the first into question.$batch05$), ($batch05$D$batch05$, $batch05$Paul never mentions Sarah's motives.$batch05$), ($batch05$E$batch05$, $batch05$This is the most popular wrong answer, because Paul does talk about volunteering happening a different way. But he is defending the *same* policy Sarah attacks, not proposing a new one. "A policy Sarah fails to consider" never appears.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT102-S4-Q21$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
